#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[])
{
    /* Too few arguments – nothing to compare */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    /* Too many arguments (including the program name) */
    if (argc > 65) {          /* 0x41 == 65 */
        puts("TOO_MANY");
        return 0;
    }

    /* Verify each argument length */
    for (int i = 1; i < argc; ++i) {
        if (strlen(argv[i]) > 1024) {   /* 0x400 == 1024 */
            puts("TOO_LONG");
            return 0;
        }
    }

    /* Longest common prefix among all arguments (argv[1] … argv[argc‑1]) */
    const char *prefix = argv[1];
    size_t pref_len = strlen(prefix);

    for (int i = 2; i < argc && pref_len > 0; ++i) {
        const char *s = argv[i];
        size_t j = 0;
        while (j < pref_len && prefix[j] == s[j]) {
            ++j;
        }
        pref_len = j;               /* shrink prefix length */
    }

    /* Output the prefix followed by a newline */
    if (pref_len > 0) {
        fwrite(prefix, 1, pref_len, stdout);
    }
    putchar('\n');

    return 0;
}
